//! Independent reference values for the rank tests (scipy).
//!
//! `tests/reference/nonparametric.json` is generated by
//! `tools/gen_nonparametric.py`; the test never runs Python.

use std::collections::BTreeMap;

use fp_core::data::{MissingPolicy, Sample};
use fp_core::hypothesis::Alternative;
use fp_core::nonparametric::{kruskal_wallis, mann_whitney, sign_test, wilcoxon_signed_rank};
use serde_json::Value;

fn reference() -> Value {
    let raw = include_str!("reference/nonparametric.json");
    serde_json::from_str(raw).expect("valid JSON reference")
}

fn sample(values: &Value) -> Sample {
    let values: Vec<f64> = values
        .as_array()
        .expect("value list")
        .iter()
        .map(|value| value.as_f64().expect("observation"))
        .collect();
    Sample::new(values, MissingPolicy::Drop).expect("sample")
}

fn close(actual: f64, expected: f64, tolerance: f64, what: &str) {
    assert!(
        (actual - expected).abs() <= tolerance,
        "{what}: {actual} vs scipy {expected}"
    );
}

#[test]
fn mann_whitney_matches_scipy() {
    let r = reference();
    let case = &r["mann_whitney"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let result = mann_whitney(
        &sample(&case["first"]),
        &sample(&case["second"]),
        Alternative::TwoSided,
    )
    .expect("mann-whitney");
    close(result.u1, case["u1"].as_f64().expect("u1"), tolerance, "U1");
    close(
        result.z.abs(),
        case["z"].as_f64().expect("z"),
        tolerance,
        "|z|",
    );
    close(
        result.p_value,
        case["p_value"].as_f64().expect("p"),
        tolerance,
        "p",
    );
    // U1 + U2 is the product of the sample sizes.
    close(
        result.u1 + result.u2,
        (result.n1 * result.n2) as f64,
        tolerance,
        "U1 + U2",
    );
}

#[test]
fn wilcoxon_matches_scipy() {
    let r = reference();
    let case = &r["wilcoxon"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let values: Vec<f64> = case["differences"]
        .as_array()
        .expect("differences")
        .iter()
        .map(|value| value.as_f64().expect("difference"))
        .collect();
    let result = wilcoxon_signed_rank(&values, Alternative::TwoSided).expect("wilcoxon");
    close(
        result.w_plus,
        case["w_plus"].as_f64().expect("w+"),
        tolerance,
        "W+",
    );
    close(
        result.w_minus,
        case["w_minus"].as_f64().expect("w-"),
        tolerance,
        "W−",
    );
    close(
        result.z.abs(),
        case["z_abs"].as_f64().expect("|z|"),
        tolerance,
        "|z|",
    );
    close(
        result.p_value,
        case["p_value"].as_f64().expect("p"),
        tolerance,
        "p",
    );
    assert_eq!(result.n, 9, "the zero difference is excluded");
}

#[test]
fn kruskal_wallis_matches_scipy() {
    let r = reference();
    let case = &r["kruskal"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let mut groups = BTreeMap::new();
    for (name, values) in case["groups"].as_object().expect("groups") {
        let values: Vec<f64> = values
            .as_array()
            .expect("group")
            .iter()
            .map(|value| value.as_f64().expect("observation"))
            .collect();
        groups.insert(name.clone(), values);
    }
    let result = kruskal_wallis(&groups).expect("kruskal");
    close(result.h, case["h"].as_f64().expect("H"), tolerance, "H");
    close(
        result.p_value,
        case["p_value"].as_f64().expect("p"),
        tolerance,
        "p",
    );
    assert_eq!(result.groups, 3);
}

#[test]
fn sign_test_matches_scipy() {
    let r = reference();
    let case = &r["sign"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let result = sign_test(
        &sample(&case["values"]),
        case["median"].as_f64().expect("median"),
    )
    .expect("sign test");
    assert_eq!(
        result.above as u64,
        case["positives"].as_u64().expect("positives")
    );
    assert_eq!(
        result.below as u64,
        case["negatives"].as_u64().expect("negatives")
    );
    assert_eq!(result.ties as u64, case["zeros"].as_u64().expect("zeros"));
    close(
        result.p_value,
        case["p_value"].as_f64().expect("p"),
        tolerance,
        "p",
    );
}
